#!/usr/bin/env bash\nset -euo pipefail\n\n# Create a temporary directory for the mock `du` binary\nMOCK_DIR=$(mktemp -d)\ncleanup() { rm -rf "$MOCK_DIR"; }\ntrap cleanup EXIT\n\n# Write a simple mock `du` that returns fixed sizes based on the basename of the argument\ncat > "$MOCK_DIR/du" <<'EOF'\n#!/usr/bin/env bash\n# Mock du: ignore options, output preset sizes for known basenames\nfor arg in "$@"; do\n  if [[ "$arg" == -* ]]; then\n    continue\n  fi\n  base=$(basename "$arg")\n  case "$base" in\n    a) echo -e "400\t$arg" ;;\n    b) echo -e "200\t$arg" ;;\n    c) echo -e "100\t$arg" ;;\n    *) echo -e "0\t$arg" ;;\n  esac\n done\nEOF\nchmod +x "$MOCK_DIR/du"\n\n# Prepend the mock directory to PATH so our script picks it up\nexport PATH="$MOCK_DIR:$PATH"\n\n# Run the utility on a dummy path (the mock du ignores the actual filesystem)\nOUTPUT=$(bash ../src/main.sh /dummy/path 3)\n\n# Extract the first column (basename) from each output line\nfirst=$(echo "$OUTPUT" | head -n1 | awk '{print $1}')\nsecond=$(echo "$OUTPUT" | head -n2 | tail -n1 | awk '{print $1}')\nthird=$(echo "$OUTPUT" | tail -n1 | awk '{print $1}')\n\n# Verify that the ordering matches the mock sizes (a > b > c)\nif [[ "$first" != "a" || "$second" != "b" || "$third" != "c" ]]; then\n  echo "Test failed: unexpected ordering"\n  echo "$OUTPUT"\n  exit 1\nfi\n\necho "All tests passed"\n
